// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.facadeimport android.content.Contextimport com.roshan.persona.vision.barcode.BarcodeScanResultimport com.roshan.persona.vision.barcode.BarcodeScannerEngineimport com.roshan.persona.vision.barcode.QrPayloadimport com.roshan.persona.vision.barcode.RegionalQrFormatimport com.roshan.persona.vision.barcode.UpiQrHandlerimport com.roshan.persona.vision.barcode.PaymentIntentResultimport com.roshan.persona.vision.core.ConfidenceTieredResultimport com.roshan.persona.vision.core.ModelManagerimport com.roshan.persona.vision.core.OmniSlmRuntimeimport com.roshan.persona.vision.detection.DetectionFrameimport com.roshan.persona.vision.detection.ObjectDetectionEngineimport com.roshan.persona.vision.detection.TieredDetectionResultimport com.roshan.persona.vision.document.DocumentScanOptionsimport com.roshan.persona.vision.document.DocumentScanResultimport com.roshan.persona.vision.document.DocumentScannerEngineimport com.roshan.persona.vision.document.RegionalVisionPackLoaderimport com.roshan.persona.vision.document.TieredDocumentScanResultimport com.roshan.persona.vision.face.FaceDetectionEngineimport com.roshan.persona.vision.face.FaceDetectionResultimport com.roshan.persona.vision.face.TieredFaceResultimport com.roshan.persona.vision.infrastructure.BatteryAdaptiveControllerimport com.roshan.persona.vision.infrastructure.FallbackChainOrchestratorimport com.roshan.persona.vision.infrastructure.LmkEvictionOrchestratorimport com.roshan.persona.vision.infrastructure.SensorDutyCyclingControllerimport com.roshan.persona.vision.infrastructure.ThermalGovernorimport com.roshan.persona.vision.memory.GraphRAGConnectorimport com.roshan.persona.vision.memory.VisualEpisodicMemoryimport com.roshan.persona.vision.ocr.OcrEngineimport com.roshan.persona.vision.ocr.OcrResultimport com.roshan.persona.vision.ocr.RgbImageimport com.roshan.persona.vision.ocr.TieredOcrResultimport com.roshan.persona.vision.screen.ScreenUnderstandingEngineimport com.roshan.persona.vision.screen.ScreenUnderstandingResultimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.StateFlow/** * NOUS — Vision Facade (Module 6 v4 — Step 6.8, FINAL). * * Single entry point for ALL vision operations. Aggregates 12+ engines + 4 * infrastructure controllers into one cohesive API that the Brain (via * [com.roshan.persona.vision.brain.OmniSlmEmbedder] + [com.roshan.persona.vision.brain.OmniSlmNerModel]) * and the UI (via ViewModel) consume. * * ## Why a Facade? * * Without a Facade, the Brain and UI would need to know about: *   - ModelManager + OmniSlmRuntime + DeviceCapabilityDetector *   - OcrEngine + ImageEnhancementPipeline + OcrFieldExtractor + PrescriptionScanner *   - ObjectDetectionEngine + ObjectDetector + MotionGatingController + RealTimeTracker *   - FaceDetectionEngine + BarcodeScannerEngine + QrPayloadParser + UpiQrHandler *   - DocumentScannerEngine + EdgeDetector + StructuredDocumentParsers + RegionalVisionPackLoader *   - VisualEpisodicMemory + GraphRAGConnector *   - ScreenUnderstandingEngine + LowVisionMode *   - ThermalGovernor + SensorDutyCyclingController + BatteryAdaptiveController + LmkEvictionOrchestrator + FallbackChainOrchestrator * * That's 20+ classes. The Facade hides them behind ONE interface. * * ## Operation Groups * * | Group              | Methods                                                      | * |--------------------|--------------------------------------------------------------| * | Omni-SLM           | [embed], [extractEntities], [captionImage], [answerQuestion]| * | OCR                | [recognizeText], [scanDocument]                              | * | Object Detection   | [detectObjects], [resetDetection]                            | * | Face Detection     | [detectFaces], [cropToFace], [isFrontal]                     | * | Barcode            | [scanBarcode], [handleUpiQr]                                 | * | Episodic Memory    | [addToMemory], [queryMemory], [clearMemory]                  | * | Graph RAG          | [saveToGraph], [queryGraphContext], [clearGraph]             | * | Screen Reader      | [startScreenReading], [readScreen], [stopScreenReading]      | * | Infrastructure     | [evacuateForLmk], [reactivateFromLmk], [getThermalState]...  | * * ## Privacy (per strategy v4 §"Privacy & Security") * *  - 100% on-device — no cloud APIs, no image uploads. *  - Episodic memory is RAM-only (encrypted serialization only for LMK survival). *  - Graph RAG requires explicit user confirmation ("save this"). *  - Government IDs require explicit per-scan consent. *  - Screen reading requires per-session consent + persistent notification. *  - Face DETECTION only — NEVER recognition (hard architectural line). * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Architecture → VisionFacade</a> */class VisionFacade(    private val modelManager: ModelManager,    private val ocrEngine: OcrEngine,    private val documentScannerEngine: DocumentScannerEngine,    private val objectDetectionEngine: ObjectDetectionEngine,    private val faceDetectionEngine: FaceDetectionEngine,    private val barcodeScannerEngine: BarcodeScannerEngine,    private val upiQrHandler: UpiQrHandler,    private val episodicMemory: VisualEpisodicMemory,    private val graphRAGConnector: GraphRAGConnector,    private val screenUnderstandingEngine: ScreenUnderstandingEngine,    private val thermalGovernor: ThermalGovernor,    private val sensorDutyCyclingController: SensorDutyCyclingController,    private val batteryAdaptiveController: BatteryAdaptiveController,    private val lmkEvictionOrchestrator: LmkEvictionOrchestrator,    private val fallbackChainOrchestrator: FallbackChainOrchestrator,    private val regionalPackLoader: RegionalVisionPackLoader,) {    // ═══════════════════════════════════════════════════════════════════════════    // 1. OMNI-SLM OPERATIONS (Unified VLA Core)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Embed text into a 384-dim vector (replaces Brain's TfIdfEmbedder).     *     * @param text the text to embed.     * @return tiered embedding result.     */    suspend fun embed(text: String): ConfidenceTieredResult<FloatArray> {        val runtime = modelManager.getOmniSlmRuntime()        if (runtime.isDisabled) {            return fallbackChainOrchestrator.runEmbeddingChain(text).let { fallback ->                if (fallback.isUsable && fallback.value != null) {                    ConfidenceTieredResult.from(fallback.value, 0.80f)                } else {                    ConfidenceTieredResult.rejected(0.0f)                }            }        }        return runtime.embed(text)    }    /**     * Extract named entities from text (replaces Brain's null NER).     */    suspend fun extractEntities(text: String): ConfidenceTieredResult<List<com.roshan.persona.vision.core.OmniSlmEntity>> {        val runtime = modelManager.getOmniSlmRuntime()        if (runtime.isDisabled) {            return ConfidenceTieredResult.rejected(0.0f)        }        return runtime.extractEntities(text)    }    /**     * Caption an image (replaces MobileViT-S).     */    suspend fun captionImage(imageBytes: ByteArray): ConfidenceTieredResult<String> {        val runtime = modelManager.getOmniSlmRuntime()        if (runtime.isDisabled) {            return ConfidenceTieredResult.rejected(0.0f)        }        return runtime.captionImage(imageBytes)    }    /**     * Answer a visual question about an image (VQA).     */    suspend fun answerQuestion(imageBytes: ByteArray, question: String): ConfidenceTieredResult<String> {        val runtime = modelManager.getOmniSlmRuntime()        if (runtime.isDisabled) {            return ConfidenceTieredResult.rejected(0.0f)        }        return runtime.answerVisualQuestion(imageBytes, question)    }    // ═══════════════════════════════════════════════════════════════════════════    // 2. OCR + DOCUMENT SCANNING    // ═══════════════════════════════════════════════════════════════════════════    /**     * Recognize text in an image.     */    suspend fun recognizeText(imageBytes: ByteArray): TieredOcrResult {        return ocrEngine.recognize(imageBytes)    }    /**     * Scan a document (edge detection + perspective + OCR + structured parsing).     */    suspend fun scanDocument(        image: RgbImage,        options: DocumentScanOptions = DocumentScanOptions.DEFAULT,    ): TieredDocumentScanResult {        return documentScannerEngine.scanDocument(image, options)    }    /**     * Quick document scan (skip edge detection — for clean scans).     */    suspend fun quickScanDocument(image: RgbImage): TieredDocumentScanResult {        return documentScannerEngine.quickScan(image)    }    /** Clear the OCR cache. */    suspend fun clearOcrCache(): Int = ocrEngine.clearCache()    // ═══════════════════════════════════════════════════════════════════════════    // 3. OBJECT DETECTION (Live Camera Intelligence)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Detect objects in a camera frame.     */    suspend fun detectObjects(frame: RgbImage): TieredDetectionResult {        return objectDetectionEngine.processFrame(frame)    }    /** Get active tracking tracks. */    fun activeTracks() = objectDetectionEngine.activeTracks()    /** Reset detection (clears tracks + motion gating). */    fun resetDetection() = objectDetectionEngine.reset()    /** Get motion gating stats. */    fun motionGatingStats() = objectDetectionEngine.motionGatingStats()    /** Get current motion state. */    fun currentMotionState() = objectDetectionEngine.currentMotionState()    // ═══════════════════════════════════════════════════════════════════════════    // 4. FACE DETECTION (DETECTION ONLY — no recognition)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Detect faces in an image (DETECTION ONLY — never recognition).     */    suspend fun detectFaces(frame: RgbImage): TieredFaceResult {        return faceDetectionEngine.detect(frame)    }    /** Crop image to largest face (for auto-crop portraits). */    suspend fun cropToFace(frame: RgbImage, marginPercent: Float = 0.20f) =        faceDetectionEngine.cropToFace(frame, marginPercent)    /** Check if all faces are smiling (group photo "say cheese"). */    suspend fun areAllSmiling(frame: RgbImage) = faceDetectionEngine.areAllSmiling(frame)    /** Check if any face has eyes closed (blink detection). */    suspend fun hasBlink(frame: RgbImage) = faceDetectionEngine.hasBlink(frame)    /** Check if largest face is frontal (Aadhaar/PAN scan quality). */    suspend fun isFrontal(frame: RgbImage) = faceDetectionEngine.isFrontal(frame)    // ═══════════════════════════════════════════════════════════════════════════    // 5. BARCODE + UPI QR    // ═══════════════════════════════════════════════════════════════════════════    /**     * Scan an image for barcodes/QR codes.     */    suspend fun scanBarcode(frame: RgbImage): ConfidenceTieredResult<BarcodeScanResult> {        return barcodeScannerEngine.scan(frame)    }    /**     * Scan for the first QR code (faster — for payment flows).     */    suspend fun scanFirstQr(frame: RgbImage) = barcodeScannerEngine.scanFirstQr(frame)    /**     * Handle a UPI QR code — build + launch payment intent.     */    suspend fun handleUpiQr(payload: QrPayload.UpiPayload): PaymentIntentResult {        return upiQrHandler.handleUpiQr(payload)    }    /** Check if a UPI app is installed. */    fun isUpiAppInstalled() = upiQrHandler.isUpiAppInstalled()    // ═══════════════════════════════════════════════════════════════════════════    // 6. VISUAL EPISODIC MEMORY (Ring Buffer)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Add a frame to the visual episodic memory ring buffer.     */    fun addToMemory(        embedding: FloatArray,        caption: String? = null,        detectedObjects: List<String> = emptyList(),        metadata: Map<String, String> = emptyMap(),    ) {        episodicMemory.addFrame(embedding, caption = caption, detectedObjects = detectedObjects, metadata = metadata)    }    /**     * Query the episodic memory ("what did I just see?").     */    fun queryMemory(queryEmbedding: FloatArray, topK: Int = 3) =        episodicMemory.query(queryEmbedding, topK)    /** Get recent frames from episodic memory. */    fun recentMemoryFrames(count: Int = 5) = episodicMemory.recentFrames(count)    /** Clear episodic memory. */    fun clearMemory() = episodicMemory.clear()    /** Enable episodic memory. */    fun enableMemory() = episodicMemory.enable()    /** Disable episodic memory. */    fun disableMemory() = episodicMemory.disable()    /** Episodic memory stats. */    fun memoryStats() = episodicMemory.stats()    // ═══════════════════════════════════════════════════════════════════════════    // 7. GRAPH RAG (Visual Knowledge Graph)    // ═══════════════════════════════════════════════════════════════════════════    /**     * Save a scanned document to the visual knowledge graph (requires user confirmation).     */    suspend fun saveToGraph(        document: com.roshan.persona.vision.ocr.StructuredDocument,        userConfirmedSave: Boolean,    ): String? {        return when (document) {            is com.roshan.persona.vision.ocr.Prescription ->                graphRAGConnector.savePrescription(document, userConfirmedSave)            is com.roshan.persona.vision.ocr.Receipt ->                graphRAGConnector.saveReceipt(document, userConfirmedSave)            is com.roshan.persona.vision.ocr.BusinessCard ->                graphRAGConnector.saveBusinessCard(document, userConfirmedSave)            is com.roshan.persona.vision.ocr.GovernmentId ->                graphRAGConnector.saveGovernmentId(document, userConfirmedSave)            else -> null        }    }    /**     * Query the graph for context about a prescription (dosage change detection).     */    suspend fun queryGraphContext(prescription: com.roshan.persona.vision.ocr.Prescription) =        graphRAGConnector.queryPrescriptionContext(prescription)    /** Clear the entire visual memory graph. */    suspend fun clearGraph() = graphRAGConnector.clearGraph()    /** Graph stats. */    fun graphStats() = graphRAGConnector.stats()    // ═══════════════════════════════════════════════════════════════════════════    // 8. SCREEN UNDERSTANDING (Visual Screen Reader)    // ═══════════════════════════════════════════════════════════════════════════    /** Start a screen reading session (requires per-session consent). */    fun startScreenReading(): Boolean = screenUnderstandingEngine.startSession()    /** Read the current screen (captures screenshot + OCR + LLM summary). */    suspend fun readScreen(): ScreenUnderstandingResult? = screenUnderstandingEngine.readScreen()    /** Stop screen reading session. */    fun stopScreenReading() = screenUnderstandingEngine.stopSession()    /** True if screen reading is active. */    fun isScreenReadingActive() = screenUnderstandingEngine.isSessionActive()    // ═══════════════════════════════════════════════════════════════════════════    // 9. INFRASTRUCTURE (Thermal + Battery + LMK + Fallback)    // ═══════════════════════════════════════════════════════════════════════════    /** Get the current thermal state (StateFlow for observation). */    val thermalState: StateFlow<com.roshan.persona.vision.infrastructure.ThermalState>        get() = thermalGovernor.thermalState    /** Get the current battery state. */    val batteryState: StateFlow<com.roshan.persona.vision.infrastructure.BatteryState>        get() = batteryAdaptiveController.batteryState    /** Get the current duty cycle state. */    val dutyCycleState: StateFlow<com.roshan.persona.vision.infrastructure.DutyCycleState>        get() = sensorDutyCyclingController.dutyCycleState    /**     * Evacuate vision from RAM for LMK survival (called on camera minimize).     */    suspend fun evacuateForLmk() = lmkEvictionOrchestrator.evacuate()    /**     * Reactivate vision after LMK evacuation (called on camera reopen).     */    suspend fun reactivateFromLmk() = lmkEvictionOrchestrator.reactivate()    /** Enable Persistent Vision Mode (prevents LMK eviction). */    fun enablePersistentVisionMode() = lmkEvictionOrchestrator.enablePersistentMode()    /** Disable Persistent Vision Mode. */    fun disablePersistentVisionMode() = lmkEvictionOrchestrator.disablePersistentMode()    /** Get thermal governor stats. */    fun thermalStats() = thermalGovernor.getCurrentState()    /** Get battery adaptive stats. */    fun batteryStats() = batteryAdaptiveController.getCurrentState()    /** Get duty cycling stats. */    fun dutyCycleStats() = sensorDutyCyclingController.stats()    /** Get LMK eviction stats. */    fun lmkStats() = lmkEvictionOrchestrator.stats()    // ═══════════════════════════════════════════════════════════════════════════    // 10. REGIONAL VISION PACKS    // ═══════════════════════════════════════════════════════════════════════════    /** Get the currently active region. */    fun getActiveRegion(): RegionalQrFormat = regionalPackLoader.getActiveRegion()    /** Download a regional vision pack. */    suspend fun downloadRegionalPack(region: RegionalQrFormat) =        regionalPackLoader.downloadPack(region)    /** Activate a regional vision pack. */    fun activateRegionalPack(region: RegionalQrFormat) =        regionalPackLoader.activatePack(region)    /** List all downloaded packs. */    fun listDownloadedPacks() = regionalPackLoader.listDownloadedPacks()    /** Total storage used by vision packs. */    fun regionalPackStorageBytes() = regionalPackLoader.totalStorageBytes()    // ═══════════════════════════════════════════════════════════════════════════    // 11. DEVICE CAPABILITY    // ═══════════════════════════════════════════════════════════════════════════    /** Get the device capability snapshot (SoC + NPU + RAM tier). */    fun deviceCapability() = modelManager.capability    /** True if Omni-SLM is available on this device. */    fun isOmniSlmAvailable(): Boolean = modelManager.capability.supportsOmniSlm    /** Get total model storage size. */    fun totalModelSizeBytes() = modelManager.totalModelSizeBytes()    /** List all stored models. */    fun listStoredModels() = modelManager.listStoredModels()    private companion object {        private const val TAG = "VisionFacade"    }}
